do $$
declare
  v_app uuid;
begin
  select id into v_app
  from core.mini_apps
  where organization_id = 'mirea' and slug = 'showcase';

  if v_app is null then
    return;
  end if;

  update core.mini_app_screens
  set json = '{"type":"scaffold","body":{"type":"singleChildScrollView","padding":{"left":20,"right":20,"top":0,"bottom":28},"child":{"type":"column","crossAxisAlignment":"stretch","children":[{"type":"appSectionTitle","title":"Ввод","subtitle":"Поля во всех состояниях","topMargin":0},{"type":"appStateScope","initial":{"name":"","q":""},"child":{"type":"column","crossAxisAlignment":"stretch","children":[{"type":"appCard","child":{"type":"column","crossAxisAlignment":"stretch","children":[{"type":"appInputField","label":"Имя · default","placeholder":"Как к тебе обращаться","stateKey":"name"},{"type":"sizedBox","height":12},{"type":"appInputField","label":"Почта · с иконкой","placeholder":"you@mirea.ru","leadingIcon":"mail","keyboardType":"email","helperText":"Университетская почта"},{"type":"sizedBox","height":12},{"type":"appInputField","label":"Группа · success","initialValue":"ИКБО-01-24","success":true},{"type":"sizedBox","height":12},{"type":"appInputField","label":"Телефон · error","initialValue":"+7 999","errorText":"Слишком короткий номер","keyboardType":"phone"},{"type":"sizedBox","height":12},{"type":"appInputField","label":"Заблокировано · disabled","initialValue":"Нельзя менять","enabled":false},{"type":"sizedBox","height":12},{"type":"appInputField","label":"Пароль","placeholder":"Минимум 8 символов","obscureText":true},{"type":"sizedBox","height":12},{"type":"appInputField","label":"Заметка · multiline","placeholder":"Что запомнить","multiline":true,"maxLength":140}]}},{"type":"sizedBox","height":8},{"type":"appIf","condition":"len(state.name) > 0","child":{"type":"appCard","child":{"type":"row","crossAxisAlignment":"center","children":[{"type":"appLineIcon","icon":"user","size":20,"color":"accent"},{"type":"sizedBox","width":10},{"type":"appText","data":"Привет, {{state.name}}!"}]},"tinted":true}},{"type":"appOverline","label":"Поиск","topPadding":18,"bottomPadding":8},{"type":"appSearchField","placeholder":"Поиск по всему приложению","stateKey":"q"},{"type":"sizedBox","height":8},{"type":"appIf","condition":"len(state.q) > 0","child":{"type":"appText","data":"Ищем: «{{state.q}}»","variant":"subtext","color":"muted"}}]}},{"type":"appOverline","label":"Форма с валидацией","topPadding":18,"bottomPadding":8},{"type":"appCard","child":{"type":"form","child":{"type":"column","crossAxisAlignment":"stretch","children":[{"type":"appInputField","id":"name","label":"Имя","placeholder":"Минимум 2 символа","minLength":2,"validationMessage":"Минимум 2 символа"},{"type":"sizedBox","height":12},{"type":"appInputField","id":"email","label":"Почта","placeholder":"you@mirea.ru","email":true,"validationMessage":"Неверный e-mail"},{"type":"sizedBox","height":12},{"type":"appCheckbox","id":"agree","label":"Согласен с правилами"},{"type":"sizedBox","height":16},{"type":"appButton","label":"Проверить","onPressed":{"actionType":"validateForm","isValid":{"actionType":"multiAction","actions":[{"actionType":"hapticFeedback","style":"medium"},{"actionType":"showToast","message":"Форма валидна","type":"success"}]}},"expanded":true}]}}},{"type":"appOverline","label":"Встроенные поля Stac","topPadding":18,"bottomPadding":8},{"type":"appCard","child":{"type":"textFormField","id":"comment","decoration":{"hintText":"Комментарий","labelText":"textFormField"},"validatorRules":[{"rule":"isLength","options":{"min":3},"message":"Минимум 3 символа"}]}},{"type":"sizedBox","height":12},{"type":"appCard","child":{"type":"column","crossAxisAlignment":"stretch","children":[{"type":"appText","data":"slider","variant":"caption","color":"muted"},{"type":"sizedBox","height":6},{"type":"slider","value":5,"min":0,"max":10,"divisions":10,"label":"5","onChanged":{"actionType":"hapticFeedback","style":"light"}}]}},{"type":"sizedBox","height":12},{"type":"appCard","child":{"type":"column","crossAxisAlignment":"stretch","children":[{"type":"appText","data":"dropdownMenu","variant":"caption","color":"muted"},{"type":"sizedBox","height":6},{"type":"dropdownMenu","hintText":"Выбери тип занятия","dropdownMenuEntries":[{"value":"lecture","label":"Лекция"},{"value":"practice","label":"Практика"},{"value":"lab","label":"Лабораторная"}],"onSelected":{"actionType":"showToast","message":"Выбрано"}}]}},{"type":"sizedBox","height":20},{"type":"appButton","label":"Назад к разделам","onPressed":{"actionType":"pop"},"variant":"text","expanded":true,"icon":"chevronL"}]}}}'::jsonb
  where app_id = v_app and path = '/inputs';
end $$;
